package com.bank.compliance;

import java.util.logging.*;

public class CharReplacementDemo {
    private static final Logger log = Logger.getLogger(CharReplacementDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatusCleanlinessAnalyzer analyzer = new StatusCleanlinessAnalyzer();

        String statuses = "AABABBA"; // A active, B blocked
        int k = 1;                   // may correct at most 1 entry
        int len = analyzer.longestUniformAfterK(statuses, k);
        log.info(() -> "Longest uniform stretch after " + k + " corrections: " + len);
    }
}

