class StatusCleanlinessAnalyzer {
    private static final Logger log = Logger.getLogger(StatusCleanlinessAnalyzer.class.getName());

    // Variable window, valid when size - maxFreq <= k. O(n) time.
    int longestUniformAfterK(String s, int k) {
        int[] count = new int[26];
        int left = 0, maxFreq = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            int ri = s.charAt(right) - 'A';
            count[ri]++;
            maxFreq = Math.max(maxFreq, count[ri]);   // never decreased on purpose
            if ((right - left + 1) - maxFreq > k) {   // too many to replace
                count[s.charAt(left) - 'A']--;
                left++;                               // shrink by exactly one
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

